+   * adj_stack_size 是向下对齐后的实际大小。曾经把 stack_base_ptr 当上界用，
+   * 会把正常栈判成 BAD、让这段取证整体失效（Codex 审查 P1）。 */
+  lo   = (uintptr_t)f.tcb->stack_base_ptr;
+  size = f.tcb->adj_stack_size;
+  hi   = lo + (uintptr_t)size;
