+                      rp >= tp && (rp - tp) <= sizeof(struct tcb_s) &&
+                      ((uintptr_t)sizeof(struct tcb_s) - (rp - tp)) >= need);
+
+    if (!in_stack && !in_tcb)
+      {
+        sched_unlock();
+        note_append(off, "stack[%s] regs=%08lx lo=%08lx size=%lu BAD\n",
+                    name, (unsigned long)rp, (unsigned long)lo,
+                    (unsigned long)size);
+        return;
+      }
+  }
