   466	/**
   467	 * @brief 把指定任务栈顶 48 个字（192 B）写进 note。
   468	 *
   469	 * 为什么需要：WDT 停喂的现场只留下 `wait=0x… wd=0`（无超时 sem_wait）和
   470	 * `nxsem_wait_slow` 里的 pc/lr —— **上层调用者在栈上**。没有这段栈切片，
   471	 * 就只能知道"卡在某把锁"，不能知道"从哪一行开始等"。
   472	 *
   473	 * 放在任务表之前：note 容量只有 16 KB，任务表会把尾部截掉（现场那份就截在
   474	 * pid=21）。栈切片按 sp 往上取，覆盖 setjmp 保存区与上层返回地址。
   475	 */
   476	static void note_stack_slice(size_t *off, FAR const char *name)
   477	{
   478	  struct note_find_s f;
   479	  uintptr_t lo;
   480	  uintptr_t hi;
   481	  uintptr_t sp;
   482	  size_t size;
   483	  int i;
   484	
   485	  /* 任务表用完之后 tcb 的引用就释放了：把"查表 + 取栈 + 读内存"整段放进
   486	   * sched_lock 里，避免任务在这一小段窗口里退出/被重建（本板单核，代价极小）。 */
   487	  sched_lock();
   488	
   489	  f.name = name;
   490	  f.tcb  = NULL;
   491	  nxsched_foreach(note_find_task, &f);
   492	
   493	  if (f.tcb == NULL)
   494	    {
   495	      sched_unlock();
   496	      note_append(off, "stack[%s] no-tcb\n", name);
   497	      return;
   498	    }
   499	
   500	  /* 本 port 的可用栈区间 = [stack_base_ptr, stack_base_ptr + adj_stack_size)：
   501	   * arm_createstack.c:161 把 stack_base_ptr 直接设为 stack_alloc_ptr（**下界**），
   502	   * adj_stack_size 是向下对齐后的实际大小。曾经把 stack_base_ptr 当上界用，
   503	   * 会把正常栈判成 BAD、让这段取证整体失效（Codex 审查 P1）。 */
   504	  lo   = (uintptr_t)f.tcb->stack_base_ptr;
   505	  size = f.tcb->adj_stack_size;
   506	  hi   = lo + (uintptr_t)size;
   507	
   508	  /* ① 先验证区间本身，再碰任何指针：非零 / 不回绕。 */
   509	  if (lo == 0 || size == 0 || hi <= lo)
   510	    {
   511	      sched_unlock();
   512	      note_append(off, "stack[%s] range lo=%08lx size=%lu BAD\n",
   513	                  name, (unsigned long)lo, (unsigned long)size);
   514	      return;
   515	    }
   516	
   517	  /* ② 再验证寄存器保存区是否**可读**：必须 4 字节对齐，且落在本任务栈或 TCB
   518	   *    本体之内 —— 只有这两块是确定属于该任务的内存。其它地址一律不读，
   519	   *    否则坏上下文/栈溢出时会在后面的 BAD 检查之前就先异常（Codex 审查 P2）。 */
   520	  {
   521	    uintptr_t rp   = (uintptr_t)f.tcb->xcp.regs;
   522	    uintptr_t tp   = (uintptr_t)f.tcb;
   523	    uintptr_t need = ((uintptr_t)REG_SP + 1u) * sizeof(uint32_t);
   524	    bool in_stack  = (rp != 0 && (rp & 3u) == 0 &&
   525	                      rp >= lo && rp <= hi && (hi - rp) >= need);
   526	    bool in_tcb    = (rp != 0 && (rp & 3u) == 0 &&
   527	                      rp >= tp && (rp - tp) <= sizeof(struct tcb_s) &&
   528	                      ((uintptr_t)sizeof(struct tcb_s) - (rp - tp)) >= need);
   529	
   530	    if (!in_stack && !in_tcb)
   531	      {
   532	        sched_unlock();
   533	        note_append(off, "stack[%s] regs=%08lx lo=%08lx size=%lu BAD\n",
   534	                    name, (unsigned long)rp, (unsigned long)lo,
   535	                    (unsigned long)size);
   536	        return;
   537	      }
   538	  }
   539	
   540	  sp = (uintptr_t)f.tcb->xcp.regs[REG_SP];
   541	
   542	  /* ③ SP 必须是区间内的 4 字节对齐地址，且剩余长度够 48 字。 */
   543	  if (sp < lo || (sp & 3u) != 0 ||
   544	      sp > hi || (hi - sp) < (uintptr_t)(48 * 4))
   545	    {
   546	      sched_unlock();
   547	      note_append(off, "stack[%s] sp=%08lx lo=%08lx size=%lu BAD\n",
   548	                  name, (unsigned long)sp, (unsigned long)lo,
   549	                  (unsigned long)size);
   550	      return;
   551	    }
   552	
   553	  note_append(off, "stack[%s] sp=%08lx lo=%08lx hi=%08lx\n",
   554	              name, (unsigned long)sp, (unsigned long)lo, (unsigned long)hi);
   555	
   556	  for (i = 0; i + 8 <= 48; i += 8)
   557	    {
   558	      FAR const uint32_t *p = (FAR const uint32_t *)(sp + (uintptr_t)(i * 4));
   559	
   560	      note_append(off, " %08lx %08lx %08lx %08lx %08lx %08lx %08lx %08lx\n",
   561	                  (unsigned long)p[0], (unsigned long)p[1],
   562	                  (unsigned long)p[2], (unsigned long)p[3],
   563	                  (unsigned long)p[4], (unsigned long)p[5],
   564	                  (unsigned long)p[6], (unsigned long)p[7]);
   565	    }
   566	
   567	  sched_unlock();
   568	}
