   709	static void lv_port_btn_timer(lv_timer_t *timer)
   710	{
   711	    btn_buttonset_t set;
   712	    lv_obj_t *mbox;
   713	#if MYVENDOR_LVGL_STALL_LOG
   714	    uint32_t now;
   715	    uint32_t gap;
   716	#endif
   717	
   718	    LV_UNUSED(timer);
   719	
   720	    /* 心跳：证明「扫描定时器本身在跑」。现场排查最缺的就是这一句 —— 没有它，
   721	     * "零 btn 事件"分不清是没人按键、还是扫描/驱动停了（这次就是分不清）。
   722	     * n 每 10 s 应前进 ≈500（20 ms 一拍）；不前进即扫描停摆。 */
   723	    {
   724	        static uint32_t s_hb_tick;
   725	        static uint32_t s_hb_n;
   726	
   727	        s_hb_n++;
   728	        if (s_hb_tick == 0u || lv_tick_elaps(s_hb_tick) >= 10000u) {
   729	            s_hb_tick = lv_tick_get();
   730	            syslog(LOG_INFO,
   731	                   "btn: scan alive n=%u set=0x%02x err=%u reopen=%u cbs=%d/%d/%d\n",
   732	                   (unsigned)s_hb_n, (unsigned)s_ctx.last,
   733	                   (unsigned)s_ctx.read_err, (unsigned)s_ctx.reopen_n,
   734	                   s_ctx.page_scroll_cb != NULL,
   735	                   s_ctx.page_confirm_cb != NULL,
   736	                   s_ctx.page_longpress_cb != NULL);
   737	        }
   738	    }
   739	
   740	    if (s_ctx.fd < 0) {
   741	        /* 设备没开成（或重开失败）：退避重试，绝不让扫描静默停摆。 */
   742	        if (lv_tick_elaps(s_ctx.last_err_log) >= 1000u) {
   743	            lv_port_btn_reopen();
   744	        }
   745	        return;
   746	    }
   747	
   748	    if (helm_pwr_is_offing()) {
   749	        s_ctx.last = lv_port_btn_read();
   750	        return;
   751	    }
   752	
   753	#if MYVENDOR_LVGL_STALL_LOG
   754	    now = lv_tick_get();
   755	    gap = s_btn_last_poll_tick ? lv_tick_elaps(s_btn_last_poll_tick) : 0;
   756	    s_btn_last_poll_tick = now;
   757	    if (gap > 80u) {
