   759	            (unsigned)gap, s_ctx.page_scroll_cb != NULL,
   760	            s_ctx.page_confirm_cb != NULL);
   761	    }
   762	#endif
   763	
   764	    set = lv_port_btn_read();
   765	    mbox = lv_port_get_active_msgbox();
   766	
   767	    /* CPU load is a 1-2 second history and cannot predict the first frame
   768	     * after input.  Raise the short interactive floor on both edges so a
   769	     * long press release also has a fresh window for its UI callback. */
   770	    if (((set ^ s_ctx.last) &
   771	         (LV_PORT_BTN_SCROLL | LV_PORT_BTN_CLICK | LV_PORT_BTN_PWR)) != 0) {
   772	        sf32lb_dvfs_interact();
   773	    }
   774	
   775	    if (helm_idle_is_sleeping()) {
   776	        if ((set & ~s_ctx.last) != 0) {
   777	            helm_idle_wake();
   778	            s_ctx.idle_swallow = true;
   779	            s_ctx.idle_swallow_tick = lv_tick_get();
   780	        }
   781	
   782	        if (s_ctx.idle_swallow) {
   783	            /* 只吞"叫醒的那一次按下"。若长时间还没回到 set==0（键被卡住、或驱动
   784	             * 一直回同一个值），这里以前会**无限期**吞掉所有按键且不打一行日志。
   785	             * 3 s 兜底：解除吞键并报一次，让按键至少还能被后续逻辑看到。 */
   786	            if (set == 0) {
   787	                s_ctx.idle_swallow = false;
   788	            } else if (lv_tick_elaps(s_ctx.idle_swallow_tick) >= 3000u) {
   789	                syslog(LOG_WARNING, "btn: idle swallow timeout set=0x%02x\n",
   790	                       (unsigned)set);
   791	                s_ctx.idle_swallow = false;
   792	            }
   793	
   794	            s_ctx.last = set;
   795	            return;
   796	        }
   797	    } else {
   798	        s_ctx.idle_swallow = false;
   799	    }
   800	
   801	    if (s_ctx.had_msgbox && mbox == NULL) {
   802	        s_ctx.focus_ready = false;
   803	    }
   804	    s_ctx.had_msgbox = (mbox != NULL);
   805	
   806	    if ((set & LV_PORT_BTN_SCROLL) && !(s_ctx.last & LV_PORT_BTN_SCROLL)) {
   807	        s_ctx.scroll_press_tick = lv_tick_get();
   808	        s_ctx.scroll_long_fired = false;
   809	        myvendor_sound_key();
   810	        BTN_LOG("KEY1 down set=0x%02x scroll_cb=%d", (unsigned)set,
   811	            s_ctx.page_scroll_cb != NULL);
   812	    }
   813	
   814	    if ((set & LV_PORT_BTN_SCROLL) && (s_ctx.last & LV_PORT_BTN_SCROLL)) {
   815	        lv_port_scroll_hold_update();
   816	    }
   817	
   818	    if (!(set & LV_PORT_BTN_SCROLL) && (s_ctx.last & LV_PORT_BTN_SCROLL)) {
   819	        BTN_LOG("KEY1 up%s set=0x%02x held=%ums",
   820	                s_ctx.scroll_long_fired ? " after-long" : "",
   821	                (unsigned)set,
