   823	        if (!s_ctx.scroll_long_fired) {
   824	            lv_port_scroll_down();
   825	        }
   826	        s_ctx.scroll_long_fired = false;
   827	    }
   828	
   829	    if ((set & LV_PORT_BTN_CLICK) && !(s_ctx.last & LV_PORT_BTN_CLICK)) {
   830	        s_ctx.click_press_tick = lv_tick_get();
   831	        s_ctx.click_long_fired = false;
   832	        myvendor_sound_ok();
   833	        BTN_LOG("KEY2 down set=0x%02x confirm_cb=%d", (unsigned)set,
   834	            s_ctx.page_confirm_cb != NULL);
   835	    }
   836	
   837	    if ((set & LV_PORT_BTN_CLICK) && (s_ctx.last & LV_PORT_BTN_CLICK)) {
   838	        lv_port_click_hold_update();
   839	    }
   840	
   841	    if (!(set & LV_PORT_BTN_CLICK) && (s_ctx.last & LV_PORT_BTN_CLICK)) {
   842	        /* 用户 2026-09-27 要求："打印我点下的模式" ⇒ 把按下时长与判定（短/长）一起打出来。 */
   843	        BTN_LOG("KEY2 up%s set=0x%02x held=%ums",
   844	                s_ctx.click_long_fired ? " after-long" : "",
   845	                (unsigned)set,
