   854	        s_ctx.click_long_fired = false;
   855	    }
   856	
   857	    if ((set & LV_PORT_BTN_PWR) && !(s_ctx.last & LV_PORT_BTN_PWR)) {
   858	        s_ctx.pwr_press_tick = lv_tick_get();
   859	        s_ctx.pwr_long_fired = false;
